import { formatEuros } from './money.js';
import { getCustomer } from './customers.js';
import { lineTotal, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text for display/printing.
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number, vatRate?: number }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  // First line: invoice number or DRAFT
  const numberLine = invoice.number ?? 'DRAFT';
  lines.push(numberLine);

  // Customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : invoice.customerId;
  lines.push(customerName);

  // Blank line
  lines.push('');

  // Invoice lines
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const lineText = `${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
    lines.push(lineText);
  }

  // Blank line
  lines.push('');

  // Calculate totals
  const totals = invoiceTotals(invoice);

  // VAT line (if VAT > 0)
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  // Total line
  lines.push(`Total: ${formatEuros(totals.total)}`);

  return lines.join('\n');
}

