/**
 * Render an invoice as plain text for display/printing.
 * @param {{ number?: string, customerId: string, dueDate?: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number, vatRate?: number }>, voucher?: { code: string, amount: number }, payments?: Array }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  // First line: invoice number or DRAFT
  const numberLine = invoice.number ?? 'DRAFT';
  lines.push(numberLine);

  // Customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : invoice.customerId;
  lines.push(customerName);

  // Blank line
  lines.push('');

  // Invoice lines
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const lineText = `${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
    lines.push(lineText);

    // Add discount for this line if it has one
    const discount = lineDiscount(line);
    if (discount > 0) {
      lines.push(`  Discount: ${formatEuros(discount)}`);
    }
  }

  // Blank line
  lines.push('');

  // Calculate totals
  const totals = invoiceTotals(invoice);

  // Voucher line (if any)
  if (invoice.voucher && invoice.voucher.amount > 0) {
    lines.push(`Voucher (${invoice.voucher.code}): ${formatEuros(invoice.voucher.amount)}`);
  }

  // VAT line (if VAT > 0)
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  // Total line
  lines.push(`Total: ${formatEuros(totals.total)}`);

  // Due date line (if available)
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Paid line (if there are payments)
  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = totals.total - balanceDue(invoice);
    lines.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return lines.join('\n');
}

