2	import assert from 'node:assert/strict';
3	import { renderInvoiceText } from '../src/render.js';
4	import { createInvoice } from '../src/invoices.js';
5	import { issueInvoice } from '../src/invoices.js';
6	
7	test('renderInvoiceText shows DRAFT for unsent invoices', () => {
8	  const r = createInvoice({
9	    customerId: 'C-001',
10	    issueDate: '2025-01-15',
11	    lines: [{ sku: 'ICON-SET', qty: 2 }],
12	  });
13	  const invoice = r.value;
14	  const text = renderInvoiceText(invoice);
15	  assert.ok(text.startsWith('DRAFT'));
16	});
17	
18	test('renderInvoiceText shows invoice number for issued invoices', () => {
19	  const r = createInvoice({
20	    customerId: 'C-001',
21	    issueDate: '2025-01-15',
22	    lines: [{ sku: 'ICON-SET', qty: 2 }],
23	  });
24	  const invoice = r.value;
25	  const r2 = issueInvoice(invoice, []);
26	  const text = renderInvoiceText(r2.value);
27	  assert.ok(text.startsWith('INV-2025-0001'));
28	});
29	
30	test('renderInvoiceText includes customer name', () => {
31	  const r = createInvoice({
32	    customerId: 'C-001',
33	    issueDate: '2025-01-15',
34	    lines: [{ sku: 'ICON-SET', qty: 1 }],
35	  });
36	  const invoice = r.value;
37	  const text = renderInvoiceText(invoice);
38	  assert.ok(text.includes('Northwind Studio'));
39	});
40	
41	test('renderInvoiceText shows all line details', () => {
42	  const r = createInvoice({
43	    customerId: 'C-001',
44	    issueDate: '2025-01-15',
45	    lines: [{ sku: 'ICON-SET', qty: 2 }],
46	  });
47	  const invoice = r.value;
48	  const text = renderInvoiceText(invoice);
49	  assert.ok(text.includes('2 × Icon set'));
50	  assert.ok(text.includes('€9.80'));
51	  assert.ok(text.includes('€19.60'));
52	});
53	
54	test('renderInvoiceText handles multiple lines', () => {
55	  const r = createInvoice({
56	    customerId: 'C-001',
57	    issueDate: '2025-01-15',
58	    lines: [
59	      { sku: 'ICON-SET', qty: 2 },
60	      { sku: 'DES-HOUR', qty: 1 },
61	    ],
62	  });
63	  const invoice = r.value;
64	  const text = renderInvoiceText(invoice);
65	  assert.ok(text.includes('2 × Icon set'));
66	  assert.ok(text.includes('1 × Design work'));
67	});
68	
69	test('renderInvoiceText shows correct totals', () => {
70	  const r = createInvoice({
71	    customerId: 'C-001',
72	    issueDate: '2025-01-15',
73	    lines: [
74	      { sku: 'ICON-SET', qty: 2 },
75	      { sku: 'DES-HOUR', qty: 1 },
76	    ],
77	  });
78	  const invoice = r.value;
79	  const text = renderInvoiceText(invoice);
80	  // ICON-SET: 2 × 980 = 1960, discount (5%) = 98, after discount = 1862, VAT (21%) = 391
81	  // DES-HOUR: 1 × 8500 = 8500, discount (5%) = 425, after discount = 8075, VAT (21%) = 1696
82	  // Subtotal: 10460, Discount: 523, VAT: 2087, Total: 12024 = €120.24
83	  assert.ok(text.includes('Total: €120.24'));
84	});
85	
86	test('renderInvoiceText has proper structure with blank lines', () => {
87	  const r = createInvoice({
88	    customerId: 'C-001',
