import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';

test('renderInvoiceText shows DRAFT for unsent invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 2 }],
  });
  const invoice = r.value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.startsWith('DRAFT'));
});

test('renderInvoiceText shows invoice number for issued invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 2 }],
  });
  const invoice = r.value;
  const r2 = issueInvoice(invoice, []);
  const text = renderInvoiceText(r2.value);
  assert.ok(text.startsWith('INV-2025-0001'));
});

test('renderInvoiceText includes customer name', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const invoice = r.value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Northwind Studio'));
});

test('renderInvoiceText shows all line details', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 2 }],
  });
  const invoice = r.value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('2 × Icon set'));
  assert.ok(text.includes('€9.80'));
  assert.ok(text.includes('€19.60'));
});

test('renderInvoiceText handles multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'ICON-SET', qty: 2 },
      { sku: 'DES-HOUR', qty: 1 },
    ],
  });
  const invoice = r.value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('2 × Icon set'));
  assert.ok(text.includes('1 × Design work'));
});

test('renderInvoiceText shows correct totals', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'ICON-SET', qty: 2 },
      { sku: 'DES-HOUR', qty: 1 },
    ],
  });
  const invoice = r.value;
  const text = renderInvoiceText(invoice);
  // ICON-SET: 2 × 980 = 1960, discount (5%) = 98, after discount = 1862, VAT (21%) = 391
  // DES-HOUR: 1 × 8500 = 8500, discount (5%) = 425, after discount = 8075, VAT (21%) = 1696
  // Subtotal: 10460, Discount: 523, VAT: 2087, Total: 12024 = €120.24
  assert.ok(text.includes('Total: €120.24'));
});

test('renderInvoiceText has proper structure with blank lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const invoice = r.value;
  const text = renderInvoiceText(invoice);
  const parts = text.split('\n');
  // Should have: number, customer, blank, line(s), blank, total
  assert.ok(parts.length >= 6);
  assert.equal(parts[2], ''); // blank line after customer
});

test('renderInvoiceText formats single item properly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const invoice = r.value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('1 × Icon set'));
  assert.ok(text.includes('€9.80'));
  // Subtotal: 980, Discount (5%): 49, After discount: 931, VAT (21%): 196, Total: 1127 = €11.27
  assert.ok(text.includes('Total: €11.27'));
});

test('renderInvoiceText formats large quantities', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 100 }],
  });
  const invoice = r.value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('100 × Icon set'));
});

test('renderInvoiceText formats expensive items', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'BRAND-BOOK', qty: 1 }],
  });
  const invoice = r.value;
  const text = renderInvoiceText(invoice);
  // BRAND-BOOK unitPrice is 245000 cents = €2,450.00
  assert.ok(text.includes('€2,450.00'));
});

test('renderInvoiceText uses formatEuros for all amounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'PRINT-A4', qty: 5 }],
  });
  const invoice = r.value;
  const text = renderInvoiceText(invoice);
  // PRINT-A4 unitPrice is 37 cents = €0.37
  // 5 × 37 = 185 cents = €1.85
  assert.ok(text.includes('€0.37'));
  assert.ok(text.includes('€1.85'));
});

test('renderInvoiceText shows line names from catalogue', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'DEV-HOUR', qty: 2 },
    ],
  });
  const invoice = r.value;
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('Design work (hour)'));
  assert.ok(text.includes('Development (hour)'));
});

test('renderInvoiceText ends with Total line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const invoice = r.value;
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.ok(lines[lines.length - 1].startsWith('Total: €'));
});

test('renderInvoiceText works with all different invoice statuses', () => {
  // Draft
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const text1 = renderInvoiceText(r1.value);
  assert.ok(text1.startsWith('DRAFT'));

  // Issued
  const r2 = issueInvoice(r1.value, []);
  const text2 = renderInvoiceText(r2.value);
  assert.ok(text2.startsWith('INV-2025-0001'));
});

test('renderInvoiceText shows VAT line when VAT > 0', () => {
  // ICON-SET has 21% VAT, gold customer gets 5% discount
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert.ok(text.includes('VAT: €'));
});

test('renderInvoiceText does not show VAT line when VAT = 0', () => {
  // WORKSHOP-DAY has 0% VAT
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert.ok(!text.includes('VAT:'));
});

test('renderInvoiceText VAT appears before total line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  let vatLineIndex = -1;
  let totalLineIndex = -1;

  for (let i = 0; i < lines.length; i++) {
    if (lines[i].startsWith('VAT:')) vatLineIndex = i;
    if (lines[i].startsWith('Total:')) totalLineIndex = i;
  }

  assert.ok(vatLineIndex !== -1, 'VAT line should exist');
  assert.ok(totalLineIndex !== -1, 'Total line should exist');
  assert.ok(vatLineIndex < totalLineIndex, 'VAT should come before Total');
});

test('renderInvoiceText calculates total including VAT', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [{ sku: 'ICON-SET', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  // C-002 is standard tier (0% discount), ICON-SET is 980 cents with 21% VAT
  // Subtotal: 980, Discount: 0, VAT: 980 * 21 / 100 = 206, Total: 1186
  assert.ok(text.includes('€1,186.00') || text.includes('€11.86'));
});

test('renderInvoiceText with mixed VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-15',
    lines: [
      { sku: 'ICON-SET', qty: 1 },
      { sku: 'PRINT-A4', qty: 1 },
    ],
  });
  const text = renderInvoiceText(r.value);
  // ICON-SET: 21% VAT, PRINT-A4: 0% VAT
  // Should show VAT line because ICON-SET has VAT
  assert.ok(text.includes('VAT: €'));
});

