      { sku: 'DES-HOUR', qty: 1 },
    ],
  });
  const invoice = r.value;
  const text = renderInvoiceText(invoice);
  // ICON-SET: 2 × 980 = 1960, discount (5%) = 98, after discount = 1862, VAT (21%) = 391
  // DES-HOUR: 1 × 8500 = 8500, discount (5%) = 425, after discount = 8075, VAT (21%) = 1696
  // Subtotal: 10460, Discount: 523, VAT: 2087, Total: 12024 = €120.24
  assert.ok(text.includes('Total: €120.24'));
});

